for i in range(7):
    for s in S:
        edges.append((i, 7 + (i+s)%7))

import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(15))
G.add_edges_from(edges)
print("edges:", len(edges))
print("bipartite:", nx.is_bipartite(G))

# Check girth by BFS from each node
def girth(G):
    g = float('inf')
    for src in G.nodes():
        dist = {src:0}
        parent = {src:None}
        queue = [src]
        while queue:
            nxt = []
            for u in queue:
                for v in G.neighbors(u):
                    if v not in dist:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        nxt.append(v)
                    elif parent[u] != v:
                        c = dist[u]+dist[v]+1
                        if c < g: g = c
            queue = nxt
    return g
print("girth:", girth(G))
